/// ErgoTree wire bytes for `03-lp-fund-tests/lp_accumulation.es`.
///
/// Provenance at generation time: pure Rust compiler — byte-match
/// with the Scala node.
pub const LP_ACCUMULATION_ERGO_TREE_HEX: &str = concat!(
    "100204000e20f7e52722204eab03cf13bea0772e0e00ee48f4a6f81396514d9a3b692d61b1e4",
    "d802d601b2a5730000d602c27201d1eced937202c2a792c17201c1a793cb72027301",
);

/// Decoded bytes for [`EMISSION_ERGO_TREE_HEX`]. Panics at startup if
/// the const hex is malformed (which would be a build-time bug, not a
/// runtime condition).
pub fn emission_ergo_tree_bytes() -> Vec<u8> {
    hex::decode(EMISSION_ERGO_TREE_HEX).expect("EMISSION_ERGO_TREE_HEX is malformed")
}

/// Decoded bytes for [`TREASURY_ACCUMULATION_ERGO_TREE_HEX`].
pub fn treasury_accumulation_ergo_tree_bytes() -> Vec<u8> {
    hex::decode(TREASURY_ACCUMULATION_ERGO_TREE_HEX)
        .expect("TREASURY_ACCUMULATION_ERGO_TREE_HEX is malformed")
}

/// Decoded bytes for [`LP_ACCUMULATION_ERGO_TREE_HEX`].
pub fn lp_accumulation_ergo_tree_bytes() -> Vec<u8> {
    hex::decode(LP_ACCUMULATION_ERGO_TREE_HEX).expect("LP_ACCUMULATION_ERGO_TREE_HEX is malformed")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_three_constants_decode_to_valid_hex() {
        let _ = emission_ergo_tree_bytes();
        let _ = treasury_accumulation_ergo_tree_bytes();
        let _ = lp_accumulation_ergo_tree_bytes();
    }

    #[test]
    fn byte_sizes_match_canonical_compile_output() {
        // Pin against drift — if a future regenerate run produces a
        // different size, the contract source changed and Phase 4
        // genesis box construction needs to be reviewed.
        assert_eq!(emission_ergo_tree_bytes().len(), 454);
        assert_eq!(treasury_accumulation_ergo_tree_bytes().len(), 72);
        assert_eq!(lp_accumulation_ergo_tree_bytes().len(), 72);
    }

    #[test]
    fn ergo_tree_header_byte_is_v0_constant_segregated() {
        // All three contracts compile with constant segregation
        // enabled (Scala default). The header byte is 0x10 = v0 +
        // hasSize=false + hasConstants=true.
        assert_eq!(emission_ergo_tree_bytes()[0], 0x10);
        assert_eq!(treasury_accumulation_ergo_tree_bytes()[0], 0x10);
        assert_eq!(lp_accumulation_ergo_tree_bytes()[0], 0x10);
    }

    #[test]
    fn treasury_and_lp_share_body_shape() {
        // emission.es constructs the treasury and LP accumulation
        // boxes with the same "preserve script + preserve value +
        // hash check" pattern, parameterized only by the 32-byte
        // hash constant. The trailing portion after the embedded
        // hash constant should therefore be identical between the
        // two contracts. Pin this so any future divergence is caught
        // — divergence would mean the two contracts grew different
        // logic and the emission.es split logic might need updating.
        let t = treasury_accumulation_ergo_tree_bytes();
        let l = lp_accumulation_ergo_tree_bytes();
        assert_eq!(t.len(), l.len());
        // The embedded hash is constant index 1: header (1B) +
        // n_constants (1B) + const[0] type tag (1B) + const[0] value
        // (1B SInt VLQ) + const[1] type+length prefix (2B) + 32-byte
        // hash. Trailing body starts at offset 1+1+1+1+2+32 = 38.
        assert_eq!(t[38..], l[38..]);
    }
}
